// HasPinnedVersionWith applies the HasEdge predicate on the "pinned_version" edge with a given conditions (other predicates).
func HasPinnedVersionWith(preds ...predicate.BlockVersion) predicate.BlockLink {
	return predicate.BlockLink(func(s *sql.Selector) {
		step := newPinnedVersionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BlockLink) predicate.BlockLink {
	return predicate.BlockLink(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BlockLink) predicate.BlockLink {
	return predicate.BlockLink(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BlockLink) predicate.BlockLink {
	return predicate.BlockLink(sql.NotPredicates(p))
}
